#[test]
fn relative_paths_collapse_to_the_name() {
    let krate = crate_of(Vec::new(), Vec::new());
    let symbols = SymbolMap::build(&[]);
    let ctx = SigCtx {
        krate: &krate,
        symbols: &symbols,
        rustdoc_name: "k",
    };
    for (written, expected) in [
        ("super::error::MountError", "MountError"),
        ("self::Local", "Local"),
        ("crate::inner::Deep", "Deep"),
        ("std::io::Error", "std::io::Error"),
    ] {
        let path = Path {
            path: written.to_owned(),
            id: Id(99),
            args: None,
        };
        assert_eq!(ctx.path_str(&path), expected);
    }
}

#[test]
fn nested_modules_are_indexed_to_their_own_anchor() {
    // root → pb → exc_data → Kind, mirroring `monty_proto::pb::exc_data::Kind`
    let krate = crate_of(
        vec![Id(1)],
        vec![
            item(1, "pb", module(vec![Id(2)])),
            item(2, "exc_data", module(vec![Id(3)])),
            item(3, "Kind", unit_struct()),
        ],
    );
    let symbols = SymbolMap::build(&[("k", &krate)]);
    assert_eq!(symbols.resolve("k", &krate, Id(3)).as_deref(), Some("#kind"));
    assert_eq!(symbols.resolve("k", &krate, Id(2)).as_deref(), Some("#exc_data"));
}

#[test]
fn variant_fields_anchor_to_the_enum() {
    let krate = crate_of(
        vec![Id(1)],
        vec![
            item(
                1,
                "Kind",
                ItemEnum::Enum(Enum {
                    generics: generics(),
                    has_stripped_variants: false,
                    variants: vec![Id(2), Id(4)],
                    impls: Vec::new(),
                }),
            ),
            item(
                2,
                "Named",
                ItemEnum::Variant(Variant {
                    kind: VariantKind::Struct {
                        fields: vec![Id(3)],
                        has_stripped_fields: false,
                    },
                    discriminant: None,
                }),
            ),
            item(3, "field", ItemEnum::StructField(Type::Primitive("u8".to_owned()))),
            item(
                4,
                "Tuple",
                ItemEnum::Variant(Variant {
                    kind: VariantKind::Tuple(vec![Some(Id(5)), None]),
                    discriminant: None,
                }),
            ),
            item(5, "0", ItemEnum::StructField(Type::Primitive("u8".to_owned()))),
        ],
    );
    let symbols = SymbolMap::build(&[("k", &krate)]);
    assert_eq!(symbols.resolve("k", &krate, Id(3)).as_deref(), Some("#kind"));
    assert_eq!(symbols.resolve("k", &krate, Id(5)).as_deref(), Some("#kind"));
}

#[test]
fn extern_abis_are_spelled_as_written() {
    let krate = crate_of(Vec::new(), Vec::new());
    let symbols = SymbolMap::build(&[]);
    let ctx = SigCtx {
        krate: &krate,
        symbols: &symbols,
        rustdoc_name: "k",
    };
    let decl = |abi: Abi| match function(abi) {
        ItemEnum::Function(f) => ctx.fn_decl("f", &f, ""),
        _ => unreachable!(),
    };
    assert_eq!(decl(Abi::Rust), "pub fn f()");
    assert_eq!(decl(Abi::C { unwind: false }), "pub extern \"C\" fn f()");
    assert_eq!(decl(Abi::C { unwind: true }), "pub extern \"C-unwind\" fn f()");
    assert_eq!(decl(Abi::System { unwind: false }), "pub extern \"system\" fn f()");
    assert_eq!(decl(Abi::Other("efiapi".to_owned())), "pub extern \"efiapi\" fn f()");
}

#[test]
fn generic_associated_types_keep_their_params() {
    let krate = crate_of(
        vec![Id(1)],
        vec![
            item(
                1,
                "Lend",
                ItemEnum::Trait(Trait {
                    is_auto: false,
                    is_unsafe: false,
                    is_dyn_compatible: false,
                    items: vec![Id(2)],
                    generics: generics(),
                    bounds: Vec::new(),
                    implementations: Vec::new(),
                }),
            ),
            item(
                2,
                "Item",
                ItemEnum::AssocType {
                    generics: Generics {
                        params: vec![GenericParamDef {
                            name: "'a".to_owned(),
                            kind: GenericParamDefKind::Lifetime { outlives: Vec::new() },
                        }],
                        where_predicates: vec![rustdoc_types::WherePredicate::LifetimePredicate {
                            lifetime: "Self".to_owned(),
                            outlives: vec!["'a".to_owned()],
                        }],
                    },
                    bounds: Vec::new(),
                    type_: None,
                    default_unstable: None,
                },
            ),
        ],
    );
    let symbols = SymbolMap::build(&[("k", &krate)]);
    let ctx = SigCtx {
        krate: &krate,
        symbols: &symbols,
        rustdoc_name: "k",
    };
    assert_snapshot!(ctx.item_decl("Lend", &krate.index[&Id(1)]), @r"
    pub trait Lend {
        type Item<'a> where Self: 'a;
    }
    ");
}

//! Exercises an installed, instrumented `monty` binary for PGO training.

use std::{
    env,
    error::Error,
    fs, io,
    path::{Path, PathBuf},
    time::Duration,
};

use monty_pool::{Checkout, OnPrint, Pool, PoolConfig, PoolError, ReplConfig, ResumeValue, TurnEvent, on_print_sync};
use monty_types::MontyObject;

/// Cases whose type check never terminates: ty (crates 0.0.14) spins on a name
/// rebound through `functools.partial` of itself in a loop. They train without
/// type checking; remove them once a ty release finishes them.
const TYPE_CHECK_HANGS: &[&str] = &["functools__partial.py", "refcount__partial_recursion_cleanup.py"];

/// Kills a worker whose turn hangs. An instrumented worker only writes its
/// profile at exit, so a kill discards everything it gathered: this exists to
/// fail the build loudly, not to skip cases silently.
const REQUEST_TIMEOUT: Duration = Duration::from_secs(60);

/// Runs Monty's test-case corpus through subprocess pool sessions.
#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let binary = find_monty_binary()?;
    println!("Training monty runtime at {}", binary.display());

    let config = PoolConfig {
        request_timeout: Some(REQUEST_TIMEOUT),
        ..PoolConfig::subprocess(binary)
    };
    let pool = Pool::new(config).await?;
    let mut test_cases = test_cases()?;
    test_cases.sort();

    let mut completed = 0;
    let mut typing_errors = 0;
    for test_case in &test_cases {
        let code = fs::read_to_string(test_case)?;
        let script_name = test_case
            .file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("main.py")
            .to_owned();
        let skip_type_check = TYPE_CHECK_HANGS.contains(&script_name.as_str());
        let mut session = pool
            .checkout(&ReplConfig {
                script_name: script_name.clone(),
                type_check: true,
                ..ReplConfig::default()
            })
            .await?;
        let mut on_print = on_print_sync(|_, _| {});

        match run_code(&mut session, &code, skip_type_check, &mut on_print).await {
            Ok(()) => {
                completed += 1;
                session.finish().await?;
            }
            Err(PoolError::Typing(_)) => {
                typing_errors += 1;
                match run_code(&mut session, &code, true, &mut on_print).await {
                    Ok(()) => {
                        completed += 1;
                        session.finish().await?;
                    }
                    Err(PoolError::Runtime(_)) => session.finish().await?,
                    Err(error) => return Err(format!("{script_name}: {error}").into()),
                }
            }
            Err(PoolError::Runtime(_)) => session.finish().await?,
            Err(error) => return Err(format!("{script_name}: {error}").into()),
        }
    }

    // A clean shutdown lets instrumented workers flush their `.profraw` data.
    // Dropping the pool kills idle workers, which can discard buffered profiles.
    pool.close().await;
    println!(
        "Exercised {} test cases, {completed} completed, {typing_errors} retried without type checking",
        test_cases.len()
    );
    Ok(())
}

/// Runs a snippet through completion, answering every suspension with fixture-like values.
async fn run_code(
    session: &mut Checkout,
    code: &str,
    skip_type_check: bool,
    on_print: OnPrint<'_>,
) -> Result<(), PoolError> {
    let mut event = session
        .feed(code, vec![], vec![], skip_type_check, &mut *on_print)
        .await?;
    loop {
        event = match event {
            TurnEvent::Complete(_) => break Ok(()),
            TurnEvent::FunctionCall { .. } => {
                session
                    .resume(ResumeValue::Return(MontyObject::none()), &mut *on_print)
                    .await?
            }
            TurnEvent::OsCall { .. } => match session.resume_from_mounts(&mut *on_print).await? {
                Some(event) => event,
                None => session.resume(ResumeValue::NotHandled, &mut *on_print).await?,
            },
            TurnEvent::NameLookup { name, .. } => {
                session
                    .resume_name_lookup(name_lookup_value(name), &mut *on_print)
                    .await?
            }
            TurnEvent::ResolveFutures { pending_call_ids, .. } => {
                let results = pending_call_ids
                    .into_iter()
                    .map(|call_id| (call_id, ResumeValue::Return(MontyObject::none())))
                    .collect();
                session.resume_futures(results, &mut *on_print).await?
            }
        };
    }
}

/// Returns representative host values for names used by the shared test corpus.
fn name_lookup_value(name: String) -> Option<MontyObject> {
    match name.as_str() {
        "add_ints" | "concat_strings" | "return_value" | "get_list" | "raise_error" | "make_point"
        | "make_mutable_point" | "make_user" | "make_empty" | "async_call" | "async_fail" => {
            Some(MontyObject::function(name, None))
        }
        "CONST_INT" => Some(MontyObject::int(42)),
        "CONST_STR" => Some(MontyObject::string("hello".to_owned())),
        #[expect(clippy::approx_constant, reason = "3.14 is the test fixture value")]
        "CONST_FLOAT" => Some(MontyObject::float(3.14)),
        "CONST_BOOL" => Some(MontyObject::bool(true)),
        "CONST_LIST" => Some(MontyObject::list([
            MontyObject::int(1),
            MontyObject::int(2),
            MontyObject::int(3),
        ])),
        "CONST_NONE" => Some(MontyObject::none()),
        "root" => Some(MontyObject::path("/mnt".to_owned())),
        _ => None,
    }
}

/// Resolves `monty` from the environment maturin prepares for PGO training.
fn find_monty_binary() -> io::Result<PathBuf> {
    let path = env::var_os("PATH").ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "PATH is not set"))?;
    let executable = if cfg!(windows) { "monty.exe" } else { "monty" };
    env::split_paths(&path)
        .map(|directory| directory.join(executable))
        .find(|candidate| candidate.is_file())
        .map(|candidate| candidate.canonicalize().unwrap_or(candidate))
        .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, format!("{executable} was not found on PATH")))
}

/// Lists the shared interpreter test cases from the workspace checkout.
fn test_cases() -> io::Result<Vec<PathBuf>> {
    let directory = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("monty-pool should be inside the workspace crates directory")
        .join("monty/test_cases");
    fs::read_dir(directory)?
        .filter_map(|entry| match entry {
            Ok(entry) if entry.path().extension().is_some_and(|extension| extension == "py") => Some(Ok(entry.path())),
            Ok(_) => None,
            Err(error) => Some(Err(error)),
        })
        .collect()
}

